#include <Arduino.h>
#include "page_s2_escalier.h"

namespace PageS2Escalier {
String html() {
  return R"rawliteral(
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Drawbot - Escalier</title>
<style>
:root{--bg:#0f172a;--panel:#020617;--card:#111827;--border:#1e293b;--text:#e5e7eb;--muted:#93a4bd;--accent:#38bdf8;--green:#22c55e;--red:#ef4444;--orange:#f97316;--purple:#a855f7;--yellow:#facc15}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Arial,Helvetica,sans-serif}.top{position:sticky;top:0;z-index:10;background:#020617;border-bottom:1px solid var(--border);padding:14px 22px;display:flex;gap:12px;align-items:center}.top a{color:var(--text);background:#1e293b;text-decoration:none;padding:12px 18px;border-radius:12px;font-weight:700}.wrap{padding:24px}.title{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:18px}.title h1{margin:0;font-size:30px}.subtitle{color:var(--muted);margin:8px 0 0}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:18px}.card{background:var(--card);border:1px solid var(--border);border-radius:18px;padding:18px;box-shadow:0 10px 30px rgba(0,0,0,.22)}.span4{grid-column:span 4}.span5{grid-column:span 5}.span6{grid-column:span 6}.span7{grid-column:span 7}.span8{grid-column:span 8}.span12{grid-column:span 12}h2{font-size:20px;margin:0 0 14px}h3{font-size:15px;color:var(--muted);margin:18px 0 10px}.form2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}label{display:block;color:#bdd7f4;margin-bottom:6px;font-size:14px}input,select{width:100%;padding:10px 12px;border-radius:12px;background:#020617;border:1px solid var(--border);color:var(--text);font-size:15px}button{border:0;border-radius:13px;color:white;font-weight:800;cursor:pointer;padding:12px 14px}.btns{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}.btn-green{background:var(--green)}.btn-red{background:var(--red)}.btn-blue{background:var(--accent);color:#082f49}.btn-orange{background:var(--orange)}.btn-dark{background:#334155}.btn-purple{background:var(--purple)}.btn-yellow{background:var(--yellow);color:#422006}.value{display:flex;justify-content:space-between;gap:12px;border-bottom:1px solid rgba(148,163,184,.16);padding:8px 0}.value span:first-child{color:var(--muted)}.value span:last-child{font-family:Consolas,monospace;font-weight:700;text-align:right}.console{height:260px;overflow:auto;background:#020617;border:1px solid var(--border);border-radius:15px;padding:12px;font-family:Consolas,monospace;color:#a7f3d0;font-size:13px;white-space:pre-wrap}.hint{background:rgba(56,189,248,.10);border:1px solid rgba(56,189,248,.28);border-radius:14px;padding:12px;color:#c7e9ff;font-size:14px;line-height:1.45}.warn{background:rgba(249,115,22,.12);border:1px solid rgba(249,115,22,.28);border-radius:14px;padding:12px;color:#fed7aa;font-size:14px;line-height:1.45}.badge{display:inline-block;border-radius:999px;padding:5px 10px;font-weight:800;font-size:12px}.ok{background:#22c55e;color:#052e16}.ko{background:#64748b}.lim{background:#f97316;color:#431407}@media(max-width:1100px){.grid{grid-template-columns:1fr}.span4,.span5,.span6,.span7,.span8,.span12{grid-column:span 1}.form2,.form3{grid-template-columns:1fr}.title{display:block}}
</style>
</head>
<body>
<nav class="top"><a href="/">Accueil</a><a href="/soutenance1">Soutenance 1</a><a href="/soutenance2">Soutenance 2</a><a href="/simulation">Simulation</a></nav>
<div class="wrap">
  <div class="title"><div><h1>Soutenance 2 — Escalier</h1><p class="subtitle">Commande robuste du stylo par cinématique inverse, réglable sans recompiler.</p></div><div class="btns"><button class="btn-red" onclick="api('/api/stop')">STOP moteurs</button><button class="btn-blue" onclick="api('/api/reset-encoders')">RESET odométrie</button></div></div>
  <div class="grid">
    <section class="card span4"><h2>1. Tests progressifs</h2><div class="hint">Ne lance pas l'escalier complet tant que la ligne droite puis le test d'un angle ne sont pas stables.</div><h3>Ligne droite</h3><label>Distance ligne test — cm</label><input id="lineDistance" type="number" value="20" step="0.1"><div class="btns"><button class="btn-blue" onclick="startLineTest()">Tester ligne droite</button></div><h3>Un seul angle</h3><div class="form3"><div><label>D1 — cm</label><input id="angleD1" type="number" value="20" step="0.1"></div><div><label>Angle — °</label><input id="angleValue" type="number" value="90" step="1"></div><div><label>D2 — cm</label><input id="angleD2" type="number" value="10" step="0.1"></div></div><div class="btns"><button class="btn-orange" onclick="startAngleTest()">Tester un angle</button></div></section>
    <section class="card span4"><h2>2. Escalier complet</h2><div class="form2"><div><label>Distance 1 — cm</label><input id="stairDist1" type="number" value="20" step="0.1"></div><div><label>Angle gauche — °</label><input id="stairAngleLeft" type="number" value="90" step="1"></div><div><label>Distance 2 — cm</label><input id="stairDist2" type="number" value="10" step="0.1"></div><div><label>Angle droite — °</label><input id="stairAngleRight" type="number" value="90" step="1"></div><div><label>Distance 3 — cm</label><input id="stairDist3" type="number" value="40" step="0.1"></div><div><label>Tolérance segment — cm</label><input id="segTol" type="number" value="0.30" step="0.01"></div></div><div class="btns"><button class="btn-green" onclick="startStair()">Lancer escalier</button><button class="btn-red" onclick="api('/api/s2/escalier/stop')">STOP follower</button></div></section>
    <section class="card span4"><h2>3. Calibration distance</h2><div class="warn">Si 20 cm demandés donnent moins que 20 cm, règle l'échelle distance. Exemple : réel 12,5 cm → 20 / 12,5 = 1,60.</div><div class="form2"><div><label>Échelle distance</label><input id="distanceScale" type="number" value="0.930" step="0.01"></div><div><label>PWM minimum</label><input id="minPwm" type="number" value="180" min="0" max="255" step="1"></div><div><label>Coef gauche cm/s/PWM</label><input id="coefL" type="number" value="0.080" step="0.001"></div><div><label>Coef droite cm/s/PWM</label><input id="coefR" type="number" value="0.080" step="0.001"></div><div><label>Seuil vitesse roue</label><input id="minCommandSpeed" type="number" value="0.15" step="0.01"></div><div><label>Rampe PWM / cycle</label><input id="pwmSlewStep" type="number" value="20" step="1"></div><div><label>Correction ligne encodeurs</label><input id="straightEncoderKp" type="number" value="22" step="1"></div><div><label>Compensation arrêt — cm</label><input id="straightStopCompensation" type="number" value="0.00" step="0.01"></div><div><label>Décélération arrêt — cm/s²</label><input id="straightStopDecel" type="number" value="0" step="10"></div><div><label>Frein arrêt — ms</label><input id="straightBrakeMs" type="number" value="80" step="10"></div></div></section>
    <section class="card span6"><h2>4. Commande du stylo</h2><div class="form3"><div><label>Vitesse stylo — cm/s</label><input id="penSpeed" type="number" value="13.0" step="0.1"></div><div><label>Lookahead — cm</label><input id="lookahead" type="number" value="4.0" step="0.1"></div><div><label>Gain cible</label><input id="targetGain" type="number" value="0.4" step="0.1"></div><div><label>Gain ligne</label><input id="lineGain" type="number" value="0.6" step="0.1"></div><div><label>V stylo max</label><input id="penSpeedMax" type="number" value="18.0" step="0.1"></div><div><label>V roue max</label><input id="wheelSpeedMax" type="number" value="18.0" step="0.1"></div><div><label>Omega max rad/s</label><input id="maxOmega" type="number" value="1.6" step="0.1"></div><div><label>Correction normale max</label><input id="maxNormalCorrection" type="number" value="2.0" step="0.1"></div><div><label>Vitesse avant minimale</label><input id="minForwardSpeed" type="number" value="0.0" step="0.1"></div></div><div class="form2" style="margin-top:12px"><div><label>Autoriser la marche arrière</label><select id="allowReverse"><option value="0">Non</option><option value="1">Oui</option></select></div><div><label>Écartement roues — cm</label><input id="wheelBase" type="number" value="8.3" step="0.1"></div><div><label>Offset stylo — cm</label><input id="penOffset" type="number" value="13.0" step="0.1"></div></div></section>
    <section class="card span6"><h2>4 bis. Mode coin serré</h2><div class="warn">Nouvelle stratégie : avant un angle, le robot ralentit puis impose un virage serré. Le coin restera légèrement arrondi, mais le rayon doit être beaucoup plus petit.</div><div class="form3"><div><label>Mode coin</label><select id="cornerMode"><option value="1">Activé</option><option value="0">Désactivé</option></select></div><div><label>Déclenchement avant coin — cm</label><input id="cornerApproach" type="number" value="1.2" step="0.1"></div><div><label>Vitesse coin — cm/s</label><input id="cornerSpeed" type="number" value="8.0" step="0.1"></div><div><label>Omega coin — rad/s</label><input id="cornerOmega" type="number" value="4.0" step="0.1"></div><div><label>Sortie coin — °</label><input id="cornerExitAngle" type="number" value="5" step="1"></div><div><label>Boost roue intérieure</label><input id="cornerInnerBoost" type="number" value="0.00" min="0" max="1" step="0.05"></div><div><label>PWM min rotation coin</label><input id="cornerTurnMinPwm" type="number" value="180" min="180" max="255" step="5"></div><div><label>Durée max coin — s</label><input id="cornerMaxDuration" type="number" value="1.8" step="0.1"></div></div><p class="muted">Pour un angle plus serré : baisse Vitesse coin et Déclenchement, augmente Omega coin. Si ça fait un point épais ou un crochet, baisse Omega ou augmente Sortie coin.</p></section>
    <section class="card span6"><h2>5. PID latéral</h2><div class="warn">Tes valeurs Kp=13 et Kd=1 sont beaucoup trop fortes pour ce contrôleur. Commence bas, puis augmente doucement.</div><div class="form3"><div><label>Kp</label><input id="kp" type="number" value="0.05" step="0.01"></div><div><label>Ki</label><input id="ki" type="number" value="0.00" step="0.01"></div><div><label>Kd</label><input id="kd" type="number" value="0.03" step="0.01"></div></div><div style="margin-top:12px"><label>Limite intégrale</label><input id="iLimit" type="number" value="10" step="1"></div><div class="btns"><button class="btn-blue" onclick="sendFollowerConfig()">Appliquer</button><button class="btn-purple" onclick="saveFollowerConfig()">Enregistrer flash</button><button class="btn-dark" onclick="loadFollowerConfig()">Recharger flash</button><button class="btn-yellow" onclick="defaultsFollowerConfig()">Valeurs défaut</button></div></section>
    <section class="card span6"><h2>6. État robot</h2><div class="value"><span>État</span><span id="state">---</span></div><div class="value"><span>Mode</span><span id="mode">---</span></div><div class="value"><span>PWM L/R</span><span id="pwmLR">---</span></div><div class="value"><span>Base X/Y</span><span id="baseXY">---</span></div><div class="value"><span>Stylo X/Y</span><span id="penXY">---</span></div><div class="value"><span>Theta</span><span id="odoTheta">---</span></div></section>
    <section class="card span6"><h2>7. Suivi du stylo</h2><div class="value"><span>Follower</span><span id="followerRunning">---</span></div><div class="value"><span>Phase</span><span id="followerPhase">---</span></div><div class="value"><span>Segment</span><span id="followerSegment">---</span></div><div class="value"><span>Cible X/Y</span><span id="targetXY">---</span></div><div class="value"><span>Erreur latérale</span><span id="latErr">---</span></div><div class="value"><span>Erreur max</span><span id="maxLatErr">---</span></div><div class="value"><span>Progression</span><span id="progress">---</span></div><div class="value"><span>V roues L/R</span><span id="wheelV">---</span></div><div class="value"><span>Omega</span><span id="omega">---</span></div><div class="value"><span>Reste avant coin</span><span id="remainingCorner">---</span></div><div class="value"><span>Erreur angle coin</span><span id="cornerErr">---</span></div><div class="value"><span>Limitations</span><span id="limits">---</span></div></section>
    <section class="card span12"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:14px"><h2 style="margin:0">Console ESP32</h2><div class="btns" style="margin-top:0"><button class="btn-dark" onclick="copyConsole()">Copier</button><span id="copyStatus" style="align-self:center;color:var(--muted);font-size:13px"></span></div></div><div id="console" class="console">Chargement...</div></section>
  </div>
</div>
<script>
function el(id){return document.getElementById(id)}
function val(id){return el(id).value}
function txt(id,v){const e=el(id); if(e)e.textContent=v}
function fmt(v,d=2){return (v===undefined||v===null||isNaN(v))?'---':Number(v).toFixed(d)}
async function copyConsole(){const box=el('console');const status=el('copyStatus');const text=box?box.textContent:'';try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const area=document.createElement('textarea');area.value=text;area.setAttribute('readonly','');area.style.position='fixed';area.style.left='-9999px';area.style.top='0';document.body.appendChild(area);area.select();document.execCommand('copy');document.body.removeChild(area)}if(status){status.textContent='Copie OK';setTimeout(()=>status.textContent='',1200)}}catch(e){if(status){status.textContent='Copie impossible';setTimeout(()=>status.textContent='',1800)}}}
function appendFollowerConfig(p){['wheelBase','penOffset','distanceScale','penSpeed','lineGain','targetGain','lookahead','penSpeedMax','wheelSpeedMax','maxOmega','maxNormalCorrection','allowReverse','minForwardSpeed','kp','ki','kd','iLimit','coefL','coefR','minPwm','minCommandSpeed','pwmSlewStep','straightEncoderKp','straightStopCompensation','straightStopDecel','straightBrakeMs','segTol','cornerMode','cornerApproach','cornerSpeed','cornerOmega','cornerExitAngle','cornerInnerBoost','cornerTurnMinPwm','cornerMaxDuration'].forEach(id=>p.append(id,val(id)))}
async function sendFollowerConfig(){const p=new URLSearchParams();appendFollowerConfig(p);await fetch('/api/s2/escalier/config/set?'+p.toString());refreshLogs()}
async function saveFollowerConfig(){const p=new URLSearchParams();appendFollowerConfig(p);await fetch('/api/s2/escalier/config/save?'+p.toString());refreshLogs()}
async function loadFollowerConfig(){const r=await fetch('/api/s2/escalier/config/load');const d=await r.json();applyConfig(d);refreshLogs()}
async function defaultsFollowerConfig(){const r=await fetch('/api/s2/escalier/config/defaults');const d=await r.json();applyConfig(d);refreshLogs()}
function applyConfig(d){const map={wheelBase:'wheelBase',penOffset:'penOffset',distanceScale:'distanceScale',penSpeed:'penSpeed',lineGain:'lineGain',targetGain:'targetGain',lookahead:'lookahead',penSpeedMax:'penSpeedMax',wheelSpeedMax:'wheelSpeedMax',maxOmega:'maxOmega',maxNormalCorrection:'maxNormalCorrection',allowReverse:'allowReverse',minForwardSpeed:'minForwardSpeed',kp:'kp',ki:'ki',kd:'kd',iLimit:'iLimit',coefL:'coefL',coefR:'coefR',minPwm:'minPwm',minCommandSpeed:'minCommandSpeed',pwmSlewStep:'pwmSlewStep',straightEncoderKp:'straightEncoderKp',straightStopCompensation:'straightStopCompensation',straightStopDecel:'straightStopDecel',straightBrakeMs:'straightBrakeMs',segTol:'segTol',cornerMode:'cornerMode',cornerApproach:'cornerApproach',cornerSpeed:'cornerSpeed',cornerOmega:'cornerOmega',cornerExitAngle:'cornerExitAngle',cornerInnerBoost:'cornerInnerBoost',cornerTurnMinPwm:'cornerTurnMinPwm',cornerMaxDuration:'cornerMaxDuration'};Object.keys(map).forEach(k=>{if(el(map[k])&&d[k]!==undefined)el(map[k]).value=(typeof d[k]==='boolean')?(d[k]?1:0):d[k]})}
async function startLineTest(){const p=new URLSearchParams();p.append('d',val('lineDistance'));appendFollowerConfig(p);await fetch('/api/s2/escalier/start-line?'+p.toString());refreshLogs()}
async function startAngleTest(){const p=new URLSearchParams();p.append('d1',val('angleD1'));p.append('a',val('angleValue'));p.append('d2',val('angleD2'));appendFollowerConfig(p);await fetch('/api/s2/escalier/start-angle?'+p.toString());refreshLogs()}
async function startStair(){const p=new URLSearchParams();p.append('d1',val('stairDist1'));p.append('aL',val('stairAngleLeft'));p.append('d2',val('stairDist2'));p.append('aR',val('stairAngleRight'));p.append('d3',val('stairDist3'));appendFollowerConfig(p);await fetch('/api/s2/escalier/start?'+p.toString());refreshLogs()}
async function api(route){await fetch(route);refreshLogs()}
async function refreshStatus(){try{const r=await fetch('/api/status');const d=await r.json();txt('state',d.state);txt('mode',d.mode);txt('pwmLR',`${d.pwmL} / ${d.pwmR}`);txt('baseXY',`${fmt(d.odoX)} / ${fmt(d.odoY)} cm`);txt('penXY',`${fmt(d.penX)} / ${fmt(d.penY)} cm`);txt('odoTheta',`${fmt(d.odoTheta,1)}°`);txt('followerRunning',d.followerRunning?'OUI':'NON');txt('followerPhase',d.followerPhase || '---');txt('followerSegment',`${d.followerSegment} / ${d.followerSegmentCount}`);txt('targetXY',`${fmt(d.followerTargetX)} / ${fmt(d.followerTargetY)} cm`);txt('latErr',`${fmt(d.followerLateralError)} cm`);txt('maxLatErr',`${fmt(d.followerMaxLateralError)} cm`);txt('progress',`${fmt(d.followerProgress)} / ${fmt(d.followerSegmentLength)} cm`);txt('wheelV',`${fmt(d.followerVLeft)} / ${fmt(d.followerVRight)} cm/s`);txt('omega',`${fmt(d.followerOmega,2)} rad/s`);txt('remainingCorner',`${fmt(d.followerRemainingToCorner)} cm`);txt('cornerErr',`${fmt(d.followerCornerAngleError,1)}°`);let lim=[];if(d.followerReverseLimited)lim.push('reverse');if(d.followerOmegaLimited)lim.push('omega');if(d.followerNormalLimited)lim.push('normal');txt('limits',lim.length?lim.join(', '):'OK')}catch(e){}}
async function refreshLogs(){try{const r=await fetch('/api/logs');const box=el('console');box.textContent=await r.text();box.scrollTop=box.scrollHeight}catch(e){el('console').textContent='Erreur lecture console'}}
loadFollowerConfig();refreshStatus();refreshLogs();setInterval(refreshStatus,500);setInterval(refreshLogs,2000);
</script>
</body>
</html>
)rawliteral";
}
}
